mapper.select:
select log_id, emp_id, login_input, result_code, is_failure, ip_address, user_agent, created_at from login_logs_51 where emp_id = #{empId}
and (ip_address like '%' + #{keyword} + '%' or login_input like '%' + #{keyword} + '%')
order by created_at desc offset #{offset} rows fetch next #{limit} rows only

select count(*)
from login_logs_51
where emp_id = #{empId}
  and is_failure = 'y'
  and created_at > (
      select isnull(max(created_at), '1900-01-01')
      from login_logs_51
      where emp_id = #{empId}
        and is_failure = 'n'
  )

select l.emp_id as EMP_ID, count(*) as FAIL_COUNT from login_logs_51 l where l.emp_id in
#{empId}
and l.is_failure = 'y' and l.created_at > ( select isnull(max(l2.created_at), '1900-01-01') from login_logs_51 l2 where l2.emp_id = l.emp_id and l2.is_failure = 'n' ) group by l.emp_id
